calls.command:
cd /tmp/work; mm singlecell python -c "
import pandas as pd
d = pd.read_csv('/tmp/work/mmc2_mapped_z.csv')
for a in ['IL5-IMO','CCL11-INFI','CCL11-IMO','CCL24','CCL17','IL-4RA','IL13RA1','IL-5R-alpha','IL17RB','CCL26','TSLP','IL-1RT2','IL-1ra','IL18-INFI','IL1RL2','CALCA','PRTN3','CTSC','FCAR','CEACAM8','MPO','TREM1','KIM1-CVDII','LCN2','PAI','TM','TFPI','SYND1','NT-proBNP-MET','GDF-15']:
    r=d[d.assay==a]
    if len(r): r=r.iloc[0]; print(f'{a:14s} OR {r.OR:6.2f} ({r.l95:.2f}-{r.u95:.2f}) p={r[\"p.value\"]:.3g} adj={r[\"adj.p.value\"]:.3g}')
    else: print(a,'not present')
"

cat > /tmp/work/report.css << 'EOF'
