cd /tmp/outputs && mm genomics pandoc AX-1177_portfolio_audit_recommendation.md -o AX-1177_portfolio_audit_recommendation.html --standalone --embed-resources --resource-path=/tmp/outputs -c /tmp/work/report.css 2>&1 | tail -3; ls -la /tmp/outputs; cat /tmp/work/prep_test.log
